55	  }
56	  const raw = values[key];
57	  // 仅接受十进制整数写法
58	  if (!/^-?\d+$/.test(raw)) {
59	    return { error: `参数 --${key} 必须为整数，实际为: ${raw}` };
60	  }
61	  const value = Number(raw);
62	  if (!Number.isSafeInteger(value) || value < min) {
63	    return { error: `参数 --${key} 必须为 >= ${min} 的整数，实际为: ${raw}` };
64	  }
65	  return { value };
66	}
