69	// 返回 { startedAt, durationNs, exitCode, reason }
70	// reason 为 null 表示正常退出（exitCode 可能非零，由调用方按阶段处理），
71	// 或为 'timeout'；进程无法启动时抛错（error.code 通常为 ENOENT/EAGAIN）。
72	function runOnce(command, timeoutMs) {
73	  return new Promise((resolve, reject) => {
74	    let child;
75	    try {
76	      child = spawn(command, {
77	        shell: true,
78	        stdio: ['ignore', 'pipe', 'pipe'],
79	        // 非 Windows 下使子 shell 成为新进程组组长，超时可整组清理，避免遗留孙进程。
80	        detached: process.platform !== 'win32',
81	      });
82	    } catch (err) {
83	      reject(err);
84	      return;
85	    }
86	
87	    // 丢弃被测命令输出，保持本工具 stdout/stderr 干净，同时排空管道避免反压。
88	    child.stdout?.on('data', () => {});
89	    child.stderr?.on('data', () => {});
90	
91	    const startedAt = new Date();
92	    const startHr = process.hrtime.bigint();
93	    let settled = false;
94	    let timedOut = false;
95	
96	    const timer = setTimeout(() => {
97	      timedOut = true;
98	      try {
99	        if (child.pid && process.platform !== 'win32') {
100	          try {
101	            process.kill(-child.pid, 'SIGKILL');
102	          } catch {
103	            child.kill('SIGKILL');
104	          }
105	        } else {
106	          child.kill('SIGKILL');
107	        }
108	      } catch {
109	        // 进程可能已退出
110	      }
111	    }, timeoutMs);
112	    timer.unref?.();
113	
114	    child.on('error', (err) => {
115	      if (settled) return;
116	      settled = true;
117	      clearTimeout(timer);
118	      reject(err);
119	    });
120	
121	    child.on('close', (code, signal) => {
122	      if (settled) return;
123	      settled = true;
124	      clearTimeout(timer);
125	      const durationNs = Number(process.hrtime.bigint() - startHr);
126	      if (timedOut) {
127	        resolve({ startedAt, durationNs, exitCode: null, reason: 'timeout' });
128	        return;
129	      }
130	      // 被信号终止（非本工具超时）同样记为 nonzero_exit，exit_code 以 null 表示无可用退出码。
131	      resolve({ startedAt, durationNs, exitCode: code, signal, reason: null });
132	    });
133	  });
134	}
