164	    return EXIT_USAGE;
165	  }
166	
167	  const command = values.command;
168	  const output = values.output;
169	  if (command === undefined || command === '') {
170	    process.stderr.write('perf-regress: --command 不能为空\n');
171	    return EXIT_USAGE;
172	  }
173	  if (output === undefined || output === '') {
174	    process.stderr.write('perf-regress: --output 不能为空\n');
175	    return EXIT_USAGE;
176	  }
177	
178	  const runsR = parsePositiveIntOption(values, 'runs', { min: 1, required: true });
179	  if (runsR.error) {
180	    process.stderr.write(`perf-regress: ${runsR.error}\n`);
181	    return EXIT_USAGE;
182	  }
183	  const warmupR = parsePositiveIntOption(values, 'warmup', { min: 0, required: false });
184	  if (warmupR.error) {
185	    process.stderr.write(`perf-regress: ${warmupR.error}\n`);
186	    return EXIT_USAGE;
187	  }
188	  const timeoutR = parsePositiveIntOption(values, 'timeout-ms', { min: 1, required: true });
189	  if (timeoutR.error) {
190	    process.stderr.write(`perf-regress: ${timeoutR.error}\n`);
191	    return EXIT_USAGE;
192	  }
193	
194	  const runs = runsR.value;
195	  const warmup = warmupR.value === undefined ? 0 : warmupR.value;
196	  const timeoutMs = timeoutR.value;
197	
198	  const samples = [];
199	  const errors = [];
200	
201	  // 先顺序预热：异常记录后继续；但进程无法启动属致命错误（退出码 2，不写 output）。
202	  for (let index = 0; index < warmup; index++) {
203	    let result;
204	    try {
205	      result = await runOnce(command, timeoutMs);
206	    } catch {
207	      reportStartupFailure('warmup', index, null);
208	      return EXIT_USAGE;
209	    }
210	    if (result.reason === 'timeout') {
211	      errors.push({ stage: 'warmup', index, reason: 'timeout', exit_code: null });
212	    } else if (isStartupExitCode(result.exitCode)) {
213	      reportStartupFailure('warmup', index, result.exitCode);
214	      return EXIT_USAGE;
215	    } else if (result.exitCode !== 0) {
216	      errors.push({ stage: 'warmup', index, reason: 'nonzero_exit', exit_code: result.exitCode });
217	    }
218	  }
219	
220	  let fatalSpawn = false;
221	
222	  // 再顺序采集：异常记录后跳过该次；进程无法启动则致命（退出码 2，不写 output）。
223	  for (let index = 0; index < runs; index++) {
224	    let result;
225	    try {
226	      result = await runOnce(command, timeoutMs);
227	    } catch {
228	      reportStartupFailure('measure', index, null);
229	      fatalSpawn = true;
230	      break;
231	    }
232	    if (result.reason === 'timeout') {
233	      errors.push({ stage: 'measure', index, reason: 'timeout', exit_code: null });
234	      continue;
235	    }
236	    if (isStartupExitCode(result.exitCode)) {
237	      reportStartupFailure('measure', index, result.exitCode);
238	      fatalSpawn = true;
239	      break;
240	    }
241	    if (result.exitCode !== 0) {
242	      errors.push({ stage: 'measure', index, reason: 'nonzero_exit', exit_code: result.exitCode });
243	      continue;
244	    }
245	    samples.push({
246	      index,
247	      started_at: result.startedAt.toISOString(),
248	      duration_ns: result.durationNs,
249	      exit_code: result.exitCode,
250	    });
251	  }
252	
253	  if (fatalSpawn) {
254	    return EXIT_USAGE;
255	  }
256	
257	  const summary = samples.length === 0
258	    ? emptySummary()
259	    : computeSummary(samples.map((s) => s.duration_ns));
260	
261	  const report = {
262	    command,
263	    runs,
264	    warmup,
265	    timeout_ms: timeoutMs,
266	    unit: 'ns',
267	    samples,
268	    summary,
269	    errors,
270	  };
271	
272	  let payload;
273	  try {
274	    payload = JSON.stringify(report, null, 2) + '\n';
275	  } catch (err) {
276	    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
277	    return EXIT_OUTPUT_ERROR;
278	  }
279	
280	  try {
281	    await fs.writeFile(output, payload, 'utf8');
282	  } catch (err) {
283	    process.stderr.write(`perf-regress: 无法写入 --output ${output}: ${err.message}\n`);
284	    return EXIT_OUTPUT_ERROR;
285	  }
286	
287	  return errors.some((e) => e.stage === 'measure') ? EXIT_MEASURE_ERROR : EXIT_OK;
288	}
289	
290	module.exports = {
291	  collect,
292	  parseArgs,
293	  runOnce,
294	  computeSummary,
295	  EXIT_OK,
296	  EXIT_USAGE,
297	  EXIT_MEASURE_ERROR,
298	  EXIT_OUTPUT_ERROR,
299	};
